# D3.js Interactive Elements: Tooltips and Selections

## Overview
D3.js provides powerful tools for making visualizations interactive through event handlers, tooltips, and dynamic styling.

## Event Handling

### Basic Event Listeners
```javascript
selection
    .on("mouseover", function(event, d) {
        // 'event' is the DOM event
        // 'd' is the data bound to this element
        // 'this' refers to the DOM element
    })
    .on("mouseout", function(event, d) {
        // Handle mouse leave
    })
    .on("click", function(event, d) {
        // Handle click
    });
```

### Common Events
- `mouseover` - Mouse enters element
- `mouseout` - Mouse leaves element
- `mousemove` - Mouse moves within element
- `click` - Element clicked
- `dblclick` - Element double-clicked
- `touchstart` / `touchend` - Touch events

## Tooltips

### Method 1: HTML Div Tooltip
Create a hidden div and show/position it on hover.

```javascript
// Create tooltip div (in initialization)
const tooltip = d3.select("body").append("div")
    .attr("class", "tooltip")
    .style("position", "absolute")
    .style("visibility", "hidden")
    .style("background", "rgba(0, 0, 0, 0.8)")
    .style("color", "white")
    .style("padding", "8px")
    .style("border-radius", "4px")
    .style("font-size", "12px");

// Add event handlers to elements
circles
    .on("mouseover", function(event, d) {
        tooltip
            .style("visibility", "visible")
            .html(`
                <strong>${d.name}</strong><br>
                Sector: ${d.sector}<br>
                Value: ${d.value}
            `);
    })
    .on("mousemove", function(event) {
        tooltip
            .style("top", (event.pageY - 10) + "px")
            .style("left", (event.pageX + 10) + "px");
    })
    .on("mouseout", function() {
        tooltip.style("visibility", "hidden");
    });
```

### Method 2: SVG Tooltip
Create tooltip using SVG elements.

```javascript
const tooltipGroup = svg.append("g")
    .attr("class", "tooltip-group")
    .style("display", "none");

tooltipGroup.append("rect")
    .attr("fill", "rgba(0, 0, 0, 0.8)")
    .attr("rx", 4);

const tooltipText = tooltipGroup.append("text")
    .attr("fill", "white")
    .attr("font-size", "12px")
    .attr("dy", "1em")
    .attr("dx", "0.5em");

circles
    .on("mouseover", function(event, d) {
        const [x, y] = d3.pointer(event);

        tooltipText.text(`${d.name}: ${d.value}`);

        const bbox = tooltipText.node().getBBox();
        tooltipGroup.select("rect")
            .attr("width", bbox.width + 16)
            .attr("height", bbox.height + 8);

        tooltipGroup
            .attr("transform", `translate(${x + 10}, ${y - 10})`)
            .style("display", "block");
    })
    .on("mouseout", function() {
        tooltipGroup.style("display", "none");
    });
```

### Using title Element (Simple)
Browser-native tooltips (limited styling):

```javascript
circles.append("title")
    .text(d => `${d.name}: ${d.value}`);
```

## Highlighting and Selection

### Highlighting on Hover
```javascript
circles
    .on("mouseover", function(event, d) {
        d3.select(this)
            .attr("stroke", "#000")
            .attr("stroke-width", 3)
            .raise();  // Bring to front
    })
    .on("mouseout", function(event, d) {
        d3.select(this)
            .attr("stroke", "none");
    });
```

### Click to Select
```javascript
let selectedElement = null;

circles.on("click", function(event, d) {
    // Remove previous selection
    if (selectedElement) {
        d3.select(selectedElement)
            .attr("stroke", "none");
    }

    // Add new selection
    d3.select(this)
        .attr("stroke", "#000")
        .attr("stroke-width", 2);

    selectedElement = this;

    // Trigger other actions (e.g., highlight table row)
    highlightTableRow(d.ticker);
});
```

## Linked Interactions

Connecting multiple visualizations:

```javascript
// Bubble chart and table synchronization
let selectedTicker = null;

// When bubble is clicked
bubbles.on("click", function(event, d) {
    selectedTicker = d.ticker;

    // Highlight bubble
    bubbles.classed("selected", false);
    d3.select(this).classed("selected", true);

    // Highlight table row
    d3.selectAll("tr")
        .classed("selected", false)
        .filter(td => td && td.ticker === d.ticker)
        .classed("selected", true);
});

// When table row is clicked
d3.selectAll("tr").on("click", function(event, d) {
    if (!d) return;

    selectedTicker = d.ticker;

    // Highlight row
    d3.selectAll("tr").classed("selected", false);
    d3.select(this).classed("selected", true);

    // Highlight bubble
    bubbles.classed("selected", false)
        .filter(bd => bd.ticker === d.ticker)
        .classed("selected", true);
});
```

## CSS Classes for Interactivity

Use CSS classes for cleaner code:

```css
/* CSS file */
.bubble {
    cursor: pointer;
    transition: opacity 0.2s;
}

.bubble:hover {
    opacity: 0.8;
}

.bubble.selected {
    stroke: #000;
    stroke-width: 3px;
}

.table-row.selected {
    background-color: #e3f2fd;
    font-weight: bold;
}
```

```javascript
// JavaScript
bubbles
    .attr("class", "bubble")
    .on("click", function(event, d) {
        bubbles.classed("selected", false);
        d3.select(this).classed("selected", true);
    });
```

## Pointer Position

Get mouse position in D3 v6:

```javascript
element.on("mousemove", function(event) {
    const [x, y] = d3.pointer(event);  // Relative to element
    console.log(x, y);
});

// Relative to specific container
element.on("mousemove", function(event) {
    const [x, y] = d3.pointer(event, svg.node());
});
```

## Transitions on Interaction

Smooth animations on hover:

```javascript
circles
    .on("mouseover", function() {
        d3.select(this)
            .transition()
            .duration(200)
            .attr("r", d => d.radius * 1.2);
    })
    .on("mouseout", function() {
        d3.select(this)
            .transition()
            .duration(200)
            .attr("r", d => d.radius);
    });
```

## Preventing Event Propagation

```javascript
element.on("click", function(event) {
    event.stopPropagation();  // Don't trigger parent's click handler
    event.preventDefault();    // Prevent default browser behavior
});
```

## Practical Example: Interactive Bubble Chart

```javascript
// Create tooltip
const tooltip = d3.select("body").append("div")
    .attr("class", "tooltip")
    .style("position", "absolute")
    .style("visibility", "hidden");

// Create bubbles
const bubbles = svg.selectAll("circle")
    .data(data)
    .join("circle")
    .attr("class", "bubble")
    .attr("cx", d => d.x)
    .attr("cy", d => d.y)
    .attr("r", d => d.radius)
    .attr("fill", d => colorScale(d.sector))
    .on("mouseover", function(event, d) {
        // Show tooltip
        tooltip
            .style("visibility", "visible")
            .html(`
                <strong>${d.ticker}</strong><br>
                ${d.name}<br>
                Sector: ${d.sector}
            `);

        // Highlight bubble
        d3.select(this)
            .attr("stroke", "#000")
            .attr("stroke-width", 2);
    })
    .on("mousemove", function(event) {
        tooltip
            .style("top", (event.pageY - 10) + "px")
            .style("left", (event.pageX + 10) + "px");
    })
    .on("mouseout", function() {
        tooltip.style("visibility", "hidden");
        d3.select(this).attr("stroke", "none");
    })
    .on("click", function(event, d) {
        // Select and sync with table
        bubbles.classed("selected", false);
        d3.select(this).classed("selected", true);

        highlightTableRow(d.ticker);

        // Scroll table to this row
        const row = document.querySelector(`tr[data-ticker="${d.ticker}"]`);
        if (row) row.scrollIntoView({ behavior: "smooth", block: "center" });
    });
```

## Best Practices

1. **Use CSS classes** - More maintainable than inline styles
2. **Add cursor: pointer** - Shows elements are interactive
3. **Provide visual feedback** - Highlight on hover
4. **Use transitions** - Smooth animations feel more polished
5. **Keep tooltips simple** - Too much info is overwhelming
6. **Test on mobile** - Touch events behave differently
7. **Debounce expensive operations** - Don't recalculate on every mousemove

## Resources
- [D3 Selection Documentation](https://github.com/d3/d3-selection)
- [D3 Transition Documentation](https://github.com/d3/d3-transition)

