// Global variables
let stocksData = [];
let selectedTicker = null;

// Chart dimensions
const width = 700;
const height = 700;
const margin = { top: 20, right: 20, bottom: 20, left: 20 };

// Initialize the visualization
async function init() {
    try {
        // Load stock descriptions
        const rawData = await d3.csv("data/stock-descriptions.csv", d => ({
            ticker: d.ticker,
            sector: d.sector,
            name: d["full name"],
            marketCap: d.marketCap && d.marketCap.trim() !== "" ? +d.marketCap : null,
            employees: d.fullTimeEmployees ? +d.fullTimeEmployees : null,
            country: d.country,
            website: d.website
        }));

        // Filter valid data (has ticker and sector)
        stocksData = rawData.filter(d => d.ticker && d.sector);

        console.log(`Loaded ${stocksData.length} stocks`);

        // Create visualizations
        createBubbleChart(stocksData);
        createDataTable(stocksData);

    } catch (error) {
        console.error("Error loading data:", error);
        document.getElementById("bubble-chart").innerHTML =
            `<p style="color: red;">Error loading data: ${error.message}</p>`;
    }
}

// Create bubble chart with force simulation
function createBubbleChart(data) {
    // Clear any existing chart
    d3.select("#bubble-chart").selectAll("*").remove();

    // Create SVG
    const svg = d3.select("#bubble-chart")
        .append("svg")
        .attr("width", width)
        .attr("height", height);

    // Get unique sectors
    const sectors = [...new Set(data.map(d => d.sector))].sort();

    // Color scale
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeCategory10);

    // Radius scale - use sqrt for proportional area
    const validMarketCaps = data.filter(d => d.marketCap !== null).map(d => d.marketCap);
    const maxMarketCap = d3.max(validMarketCaps);

    const radiusScale = d3.scaleSqrt()
        .domain([0, maxMarketCap])
        .range([5, 50]);

    // Calculate cluster positions for each sector
    const sectorCount = sectors.length;
    const clusterCenters = {};

    sectors.forEach((sector, i) => {
        const angle = (i / sectorCount) * 2 * Math.PI;
        const radius = Math.min(width, height) * 0.25;
        clusterCenters[sector] = {
            x: width / 2 + radius * Math.cos(angle),
            y: height / 2 + radius * Math.sin(angle)
        };
    });

    // Prepare node data
    const nodes = data.map(d => ({
        ...d,
        radius: d.marketCap !== null ? radiusScale(d.marketCap) : 15, // ETFs get uniform size
        x: Math.random() * width,
        y: Math.random() * height
    }));

    // Create force simulation
    const simulation = d3.forceSimulation(nodes)
        .force("charge", d3.forceManyBody().strength(-2))
        .force("x", d3.forceX(d => clusterCenters[d.sector].x).strength(0.5))
        .force("y", d3.forceY(d => clusterCenters[d.sector].y).strength(0.5))
        .force("collision", d3.forceCollide().radius(d => d.radius + 2))
        .force("center", d3.forceCenter(width / 2, height / 2).strength(0.05))
        .on("tick", ticked);

    // Create bubbles
    const bubbles = svg.selectAll(".bubble")
        .data(nodes)
        .join("circle")
        .attr("class", "bubble")
        .attr("r", d => d.radius)
        .attr("fill", d => colorScale(d.sector))
        .on("mouseover", handleMouseOver)
        .on("mousemove", handleMouseMove)
        .on("mouseout", handleMouseOut)
        .on("click", handleBubbleClick);

    // Create labels (ticker symbols)
    const labels = svg.selectAll(".bubble-label")
        .data(nodes)
        .join("text")
        .attr("class", "bubble-label")
        .text(d => d.ticker)
        .style("font-size", d => {
            // Scale font size based on bubble radius
            if (d.radius < 15) return "9px";
            if (d.radius < 25) return "10px";
            if (d.radius < 35) return "11px";
            return "12px";
        });

    // Tick function to update positions
    function ticked() {
        bubbles
            .attr("cx", d => d.x)
            .attr("cy", d => d.y);

        labels
            .attr("x", d => d.x)
            .attr("y", d => d.y);
    }

    // Create legend
    createLegend(svg, sectors, colorScale);

    // Tooltip handlers
    const tooltip = d3.select("#tooltip");

    function handleMouseOver(event, d) {
        // Only show tooltip for stocks with market cap (not ETFs)
        if (d.marketCap !== null) {
            tooltip
                .style("visibility", "visible")
                .html(`
                    <strong>${d.ticker}</strong><br>
                    ${d.name}<br>
                    Sector: ${d.sector}
                `);
        }

        // Highlight bubble
        d3.select(this)
            .attr("stroke", "#000")
            .attr("stroke-width", 2);
    }

    function handleMouseMove(event) {
        tooltip
            .style("top", (event.pageY - 10) + "px")
            .style("left", (event.pageX + 10) + "px");
    }

    function handleMouseOut() {
        tooltip.style("visibility", "hidden");

        // Remove highlight if not selected
        if (!d3.select(this).classed("selected")) {
            d3.select(this)
                .attr("stroke", "#fff")
                .attr("stroke-width", 1.5);
        }
    }

    function handleBubbleClick(event, d) {
        selectedTicker = d.ticker;

        // Update bubble selection
        bubbles.classed("selected", false);
        d3.select(this).classed("selected", true);

        // Sync with table
        highlightTableRow(d.ticker);
    }
}

// Create legend
function createLegend(svg, sectors, colorScale) {
    const legendX = width - 160;
    const legendY = 30;

    const legend = svg.append("g")
        .attr("class", "legend")
        .attr("transform", `translate(${legendX}, ${legendY})`);

    // Background
    const bgHeight = sectors.length * 25 + 20;
    legend.append("rect")
        .attr("class", "legend-background")
        .attr("x", -10)
        .attr("y", -25)
        .attr("width", 150)
        .attr("height", bgHeight)
        .attr("rx", 4);

    // Title
    legend.append("text")
        .attr("class", "legend-title")
        .attr("x", 0)
        .attr("y", -10)
        .text("Sector");

    // Legend items
    const legendItems = legend.selectAll(".legend-item")
        .data(sectors)
        .join("g")
        .attr("class", "legend-item")
        .attr("transform", (d, i) => `translate(0, ${i * 25})`);

    legendItems.append("circle")
        .attr("cx", 8)
        .attr("cy", 0)
        .attr("r", 7)
        .attr("fill", d => colorScale(d));

    legendItems.append("text")
        .attr("x", 20)
        .attr("y", 0)
        .attr("dy", "0.35em")
        .text(d => d)
        .style("font-size", "12px");
}

// Create data table
function createDataTable(data) {
    const tableContainer = d3.select("#data-table");

    // Create table element
    const table = tableContainer.append("table");

    // Create header
    const thead = table.append("thead");
    const headerRow = thead.append("tr");

    headerRow.selectAll("th")
        .data(["Ticker", "Company Name", "Sector", "Market Cap"])
        .join("th")
        .text(d => d);

    // Create body
    const tbody = table.append("tbody");

    // Sort data by ticker
    const sortedData = [...data].sort((a, b) => a.ticker.localeCompare(b.ticker));

    // Get sectors and color scale for indicator dots
    const sectors = [...new Set(data.map(d => d.sector))].sort();
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeCategory10);

    // Create rows
    const rows = tbody.selectAll("tr")
        .data(sortedData)
        .join("tr")
        .attr("data-ticker", d => d.ticker)
        .on("click", handleRowClick);

    // Add cells
    rows.each(function(d) {
        const row = d3.select(this);

        // Ticker
        row.append("td").text(d.ticker);

        // Company name
        row.append("td").text(d.name);

        // Sector with color indicator
        const sectorCell = row.append("td");
        sectorCell.append("span")
            .attr("class", "sector-indicator")
            .style("background-color", colorScale(d.sector));
        sectorCell.append("span")
            .text(d.sector);

        // Market Cap (formatted)
        row.append("td").text(d.marketCap !== null ? formatMarketCap(d.marketCap) : "N/A");
    });

    function handleRowClick(event, d) {
        selectedTicker = d.ticker;

        // Update table selection
        rows.classed("selected", false);
        d3.select(this).classed("selected", true);

        // Sync with bubble chart
        highlightBubble(d.ticker);

        // Scroll bubble into view if needed (optional enhancement)
    }
}

// Helper function to format market cap
function formatMarketCap(value) {
    if (value >= 1e12) {
        return (value / 1e12).toFixed(2) + "T";
    } else if (value >= 1e9) {
        return (value / 1e9).toFixed(2) + "B";
    } else if (value >= 1e6) {
        return (value / 1e6).toFixed(2) + "M";
    }
    return value.toFixed(0);
}

// Highlight table row by ticker
function highlightTableRow(ticker) {
    d3.selectAll("tbody tr").classed("selected", false);
    d3.selectAll("tbody tr")
        .filter(function(d) { return d && d.ticker === ticker; })
        .classed("selected", true)
        .node()?.scrollIntoView({ behavior: "smooth", block: "center" });
}

// Highlight bubble by ticker
function highlightBubble(ticker) {
    d3.selectAll(".bubble").classed("selected", false);
    d3.selectAll(".bubble")
        .filter(function(d) { return d.ticker === ticker; })
        .classed("selected", true);
}

// Initialize on page load
init();

